{'code': "import qgis.utils
p = qgis.utils.plugins.get('geo_webview')
info = {'loaded': p is not None, 'type': type(p).__name__ if p else None}
if p:
    info['attrs'] = [a for a in dir(p) if not a.startswith('_')]
    b = getattr(p, 'bridge', None)
    info['bridge'] = type(b).__name__ if b else None
    if b and hasattr(b, 'pluginInfo'):
        try:
            pi = b.pluginInfo()
            info['pluginInfo'] = {k: v for k, v in pi.items() if k != 'methods'}
            info['methods'] = [m.get('name') for m in pi.get('methods', [])] if isinstance(pi.get('methods'), list) else pi.get('methods')
        except Exception as e:
            info['pluginInfo_error'] = str(e)
    dlg = getattr(p, 'dialog', None) or getattr(p, 'dlg', None) or getattr(p, 'dockwidget', None)
    info['dialog_visible'] = dlg.isVisible() if dlg and hasattr(dlg, 'isVisible') else None
result = info"}

{'code': "import qgis.utils, json
p = qgis.utils.plugins.get('geo_webview')
info = {}
b = getattr(p, 'bridge', None)
try:
    pi = b.pluginInfo()
    info['pluginInfo_raw'] = pi if isinstance(pi, str) else json.dumps(pi, ensure_ascii=False, default=str)[:3000]
except Exception as e:
    info['pluginInfo_error'] = str(e)
panel = getattr(p, 'panel', None)
info['panel'] = type(panel).__name__ if panel else None
info['panel_visible'] = panel.isVisible() if panel and hasattr(panel, 'isVisible') else None
sm = getattr(p, 'server_manager', None)
info['server_manager'] = type(sm).__name__ if sm else None
info['server_port'] = getattr(p, 'server_port', None)
if sm:
    for a in ('is_running', 'running', 'port', 'url'):
        if hasattr(sm, a):
            v = getattr(sm, a)
            info['sm_'+a] = v() if callable(v) else v
result = info"}
